#include <bits/stdc++.h>
using namespace std;

long long gp(vector<long long>& prefix,int n,int single,int pair){
    int tri=n-single-pair;
    int f=single;
    int s=f+2*pair;
    int third=s+3*tri;
    
    long long yxz=6* prefix[f];
    yxz+=4*(prefix[s]-prefix[f]);
    yxz+=3*(prefix[third]-prefix[s]);
    return yxz;
    
}
int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    vector<long long >arr(3*n);
	    for(int i=0;i<3*n;i++){
	        cin>>arr[i];
	    }
	    sort(arr.rbegin(),arr.rend());
	    vector<long long>prefix(3*n+1,0);
	    for(int i=0;i<3*n;i++){
	        prefix[i+1]=prefix[i]+arr[i];
	        
	    }
	    long long ans=0;
	    int pair=n;
	    for(int single=0;single<=n;single++){
	        if(pair>n-single){
	            pair=n-single;
	        }
	        while(pair>0){
	            long long curr=gp(prefix,n,single,pair);
	            long long prev=gp(prefix,n,single,pair-1);
	            if(prev>=curr){
	                pair--;
	            }else{
	                break;
	            }
	        }
	        long long profit=gp(prefix,n, single,pair);
	        if(profit>ans)ans=profit;
	        
	    }
	    cout<<ans<<endl;
	    
	}
	return 0;

}
